    def count_edges(grid):
        total = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] == '?':
                    continue
                if j + 1 < n:
                    if grid[i][j] != grid[i][j+1]:
                        total += 1
                if i + 1 < n:
                    if grid[i][j] != grid[i+1][j]:
                        total += 1
        return total

    def solve(grid):
        n = len(grid)
        best = 0
        for mask in range(1 << (n * n)):
            grid2 = [row[:] for row in grid]
            ok = True
            for i in range(n):
                for j in range(n):
                    if grid2[i][j] == '?':
                        grid2[i][j] = 'B' if (mask >> (i * n + j)) & 1 else 'W'
